import json,pathlib,hashlib,sys,collections,re
base=pathlib.Path('output/hris-porting-blueprint-2026-09-09'); path=base/'coding-readiness/semantic-remediation/tim-base-exact.proposal.v1.json'; raw=path.read_bytes();p=json.loads(raw)
sys.path.insert(0,str(base/'coding-readiness'))
from validate_modern_semantic_field_lineage import validate_semantic_field_lineage,load_base_tables
v=validate_semantic_field_lineage(p,{},load_base_tables())
print('ORACLE',json.dumps({'status':v.validation_status,'readiness_pass':v.readiness_pass,'validationMode':v.validation_mode,'counts':v.counts,'errors':[{'code':x.code,'where':x.where,'message':x.message} for x in v.errors]},ensure_ascii=False))
catalog={}
for t in p['tableSpecifications']:catalog[t['tableName']]={c['name']:c for c in [t['idColumn']]+t['columns']}
for t in p['preservedInfrastructure']:catalog[t['tableName']]={c['name']:c for c in t['columns']}
required=[];typedDup=[];ruleMissing=[];ruleIndex={r['ruleId']:r for r in p['derivationRules']};sourceKinds=collections.Counter();ownerOnly=[];generation=[];clock=[]
for i,l in enumerate(p['operationFieldLineage']):
 seen=set()
 for j,x in enumerate(l['typedSources']):
  sourceKinds[x['kind']]+=1
  if x['source'] in seen:typedDup.append([i,j,x['source']])
  seen.add(x['source'])
  if x.get('kind')=='REFETCHED_OWNER_SNAPSHOT' and set(x['inputs'])=={'principal.tenantId','principal.publicId'}:ownerOnly.append([i,j,x['ownerContractRef']])
  if x.get('kind')=='GENERATED_BUSINESS_ID' and not x.get('generation'):generation.append([i,j,x['source'],x['type']])
  if x['source'].endswith(('_created_at','_posted_at','_updated_at')) and not any('ownerClock.' in z for z in x['inputs']):clock.append([i,j,x['source']])
 for j,r in enumerate(l['requiredColumnSources']):
  if r['table'] not in catalog or r['column'] not in catalog[r['table']]: required.append([i,j,r['table'],r['column']])
  if r.get('ruleId') not in ruleIndex:ruleMissing.append([i,j,r.get('ruleId')])
routes=collections.defaultdict(list)
for i,o in enumerate(p['operationDeltas']):routes[(o['method'],re.sub(r'\{[^}]+\}','{id}',o['path']).rstrip('/'))].append([i,o['operationId']])
future=[];targets=collections.defaultdict(list)
for i,t in enumerate(p['tableSpecifications']):
 for j,f in enumerate(t['foreignKeys']):
  if f['targetTable'] in [x['tableName'] for x in p['tableSpecifications'][i+1:]]: future.append([i,j,t['tableName'],f['targetTable']])
  targets[t['tableName']].append(f['targetTable'])
# Concrete reciprocal CREATE-time cycle, not a DB execution.
cycles=[]
for a,bs in targets.items():
 for b in bs:
  if b!=a and a in targets.get(b,[]) and sorted([a,b]) not in cycles:cycles.append(sorted([a,b]))
manif=[{'path':k,'expected':h,'actual':hashlib.sha256((base/k).read_bytes()).hexdigest(),'match':h==hashlib.sha256((base/k).read_bytes()).hexdigest()} for k,h in p['inputManifest'].items()]
print('CLOSURE',json.dumps({'sourceSha256':hashlib.sha256(raw).hexdigest(),'operationIdsUnique':len({o['operationId'] for o in p['operationDeltas']})==len(p['operationDeltas']),'operationLineageIdsExact':[o['operationId'] for o in p['operationDeltas']]==[l['operationId'] for l in p['operationFieldLineage']],'requiredColumnRows':sum(len(l['requiredColumnSources']) for l in p['operationFieldLineage']),'requiredColumnTargetMissing':required,'typedSourceDuplicate':typedDup,'derivationRuleMissing':ruleMissing,'kinds':sourceKinds,'ownerRefsTenantActorOnly':len(ownerOnly),'firstOwnerRefs':ownerOnly[:3],'generatedWithoutGenerationContract':len(generation),'generatedBigInt':sum(t=='BIGINT' for _,_,_,t in generation),'ownerClockDependencyAbsent':len(clock),'normalizedRouteDuplicates':{str(k):v for k,v in routes.items() if len(v)>1},'forwardCreateReferences':len(future),'firstForwardReferences':future[:5],'reciprocalCreateCycles':cycles,'inputManifests':manif},ensure_ascii=False))
